const USER_ID=1,$=s=>document.querySelector(s),names={dashboard:'Dashboard',workouts:'Workouts',meals:'Meals',goals:'Goals',progress:'Progress',analytics:'Analytics',profile:'Profile',settings:'Settings'};let workouts=[],editingId=null,deletingId=null;
const mock={stats:[['Workouts this week','4'],['Workout time','3h 25m'],['Calories burned','2,450 kcal'],['Current streak','7 days']],days:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],bars:[24,58,0,78,48,94,0],goals:[['Weight goal','65 kg to 60 kg',72],['Weekly workout goal','4 / 5 workouts',80]],nutrition:[['Protein','120 g'],['Carbs','210 g'],['Fat','55 g']],recent:[['Run','Morning Run','Today','30 min'],['Gym','Upper Body Workout','Yesterday','45 min'],['Meal','Chicken Rice Bowl','Today','550 kcal']]};
function renderDashboard(){ $('#stats').innerHTML=mock.stats.map(x=>`<article><div class="stat-label">${x[0]}</div><strong>${x[1]}</strong><small>Your fitness overview</small></article>`).join('');$('#week-bars').innerHTML=mock.days.map((x,i)=>`<div class="day ${mock.bars[i]?'active':''}"><i style="height:${mock.bars[i]||8}%"></i><span>${x}</span></div>`).join('');$('#goals-list').innerHTML=mock.goals.map(x=>`<article class="goal"><div class="goal-top"><strong>${x[0]}</strong><span>${x[1]}</span></div><p>Progress toward your target</p><div class="progress"><i style="width:${x[2]}%"></i></div><p class="percent">${x[2]}% complete</p></article>`).join('');$('#nutrition').innerHTML=mock.nutrition.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$('#recent-list').innerHTML=mock.recent.map(x=>`<article class="activity"><i>${x[0]}</i><div><b>${x[1]}</b><small>${x[2]}</small></div><span>${x[3]}</span></article>`).join('')}
function go(page){const dashboard=page==='dashboard',isWorkouts=page==='workouts';$('#dashboard').classList.toggle('hidden',!dashboard);$('#workouts').classList.toggle('hidden',!isWorkouts);$('#coming').classList.toggle('hidden',dashboard||isWorkouts);$('#page-title').textContent=names[page];$('#kicker').textContent=dashboard?'YOUR PERSONAL SPACE':'FITNESS TRACKER';$('#coming-title').textContent=names[page];document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(isWorkouts)loadWorkouts();$('#more-menu').classList.add('hidden');scrollTo({top:0,behavior:'smooth'})}
function formatMinutes(min){return min>=60?`${Math.floor(min/60)}h ${min%60}m`:`${min} min`}function formatDate(date){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${date}T00:00:00`))}
function summary(){const total=workouts.length,duration=workouts.reduce((n,x)=>n+x.duration,0),calories=workouts.reduce((n,x)=>n+x.caloriesBurned,0),average=total?Math.round(duration/total):0;$('#workout-summary').innerHTML=[['Total workouts',total],['Total workout time',formatMinutes(duration)],['Calories burned',`${calories.toLocaleString()} kcal`],['Avg duration',`${average} min`]].map(x=>`<article><div class="stat-label">${x[0]}</div><strong>${x[1]}</strong><small>From your workout history</small></article>`).join('')}
function renderWorkouts(){summary();const content=$('#workout-content');if(!workouts.length){content.innerHTML='<div class="state"><span class="tile">Run</span><h3>No workouts yet</h3><p>Start tracking your workouts to see your progress here.</p><button class="button primary" id="empty-add">Add Workout</button></div>';$('#empty-add').onclick=openAdd;return}content.innerHTML=`<table class="workout-table"><thead><tr><th>Date</th><th>Workout</th><th>Duration</th><th>Calories</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${workouts.map(x=>`<tr><td>${formatDate(x.date)}</td><td class="workout-type">${escapeHtml(x.type)}</td><td>${x.duration} min</td><td>${x.caloriesBurned} kcal</td><td class="notes">${escapeHtml(x.notes||'No notes')}</td><td><div class="actions"><button class="action" data-edit="${x.id}">Edit</button><button class="action delete-action" data-delete="${x.id}">Delete</button></div></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEdit(Number(b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>openDelete(Number(b.dataset.delete)))}
async function loadWorkouts(){const content=$('#workout-content');content.innerHTML='<div class="state">Loading workouts...</div>';try{const response=await fetch(`/api/workouts/user/${USER_ID}`);if(!response.ok)throw Error(`HTTP ${response.status}`);workouts=(await response.json()).sort((a,b)=>b.date.localeCompare(a.date));renderWorkouts()}catch(error){console.error('Unable to load workouts:',error);$('#workout-summary').innerHTML='';content.innerHTML='<div class="state"><h3>Unable to load workouts.</h3><p>Please check that the backend is running and try again.</p><button class="button secondary" id="state-retry">Retry</button></div>';$('#state-retry').onclick=loadWorkouts}}
function openAdd(){editingId=null;$('#modal-title').textContent='Add Workout';$('#save-workout').textContent='Add Workout';$('#workout-form').reset();$('#workout-date').value=new Date().toISOString().slice(0,10);$('#form-error').classList.add('hidden');$('#workout-modal').classList.remove('hidden');$('#workout-date').focus()}function openEdit(id){const x=workouts.find(w=>w.id===id);if(!x)return;editingId=id;$('#modal-title').textContent='Edit Workout';$('#save-workout').textContent='Save Changes';$('#workout-date').value=x.date;$('#workout-type').value=x.type;$('#workout-duration').value=x.duration;$('#workout-calories').value=x.caloriesBurned;$('#workout-notes').value=x.notes||'';$('#form-error').classList.add('hidden');$('#workout-modal').classList.remove('hidden')}function closeModal(){$('#workout-modal').classList.add('hidden')}
async function saveWorkout(event){event.preventDefault();const form=$('#workout-form');if(!form.reportValidity())return;const payload={user:{id:USER_ID},date:$('#workout-date').value,type:$('#workout-type').value.trim(),duration:Number($('#workout-duration').value),caloriesBurned:Number($('#workout-calories').value),notes:$('#workout-notes').value.trim()};if(payload.duration<1||payload.caloriesBurned<0)return showFormError('Check the duration and calories values.');try{const response=await fetch(editingId?`/api/workouts/${editingId}`:'/api/workouts',{method:editingId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(`HTTP ${response.status}`);closeModal();toast(editingId?'Workout updated successfully.':'Workout added successfully.');await loadWorkouts()}catch(error){console.error('Unable to save workout:',error);showFormError('Unable to save workout. Please try again.')}}function showFormError(message){const error=$('#form-error');error.textContent=message;error.classList.remove('hidden')}
function openDelete(id){deletingId=id;$('#delete-modal').classList.remove('hidden')}async function deleteWorkout(){try{const response=await fetch(`/api/workouts/${deletingId}`,{method:'DELETE'});if(!response.ok)throw Error(`HTTP ${response.status}`);$('#delete-modal').classList.add('hidden');toast('Workout deleted successfully.');await loadWorkouts()}catch(error){console.error('Unable to delete workout:',error);$('#delete-modal').classList.add('hidden');toast('Unable to delete workout. Please try again.',true)}}function toast(message,error=false){const element=$('#toast');element.textContent=message;element.classList.toggle('error',error);element.classList.remove('hidden');setTimeout(()=>element.classList.add('hidden'),3200)}function escapeHtml(value){const div=document.createElement('div');div.textContent=value;return div.innerHTML}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();go(nav.dataset.page)}if(e.target.matches('[data-close-modal]'))closeModal();if(e.target.matches('[data-close-delete]'))$('#delete-modal').classList.add('hidden')});$('#add-workout').onclick=openAdd;$('#retry-workouts').onclick=loadWorkouts;$('#workout-form').onsubmit=saveWorkout;$('#more').onclick=()=>$('#more-menu').classList.toggle('hidden');$('#today').textContent=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date());fetch('/api/test').then(r=>r.ok?r.json():Promise.reject()).then(()=>{$('#connection').classList.add('online');$('#connection').lastChild.textContent=' Backend connected'}).catch(()=>{$('#connection').classList.add('offline');$('#connection').lastChild.textContent=' Backend unavailable'});renderDashboard();

let meals=[],editingMealId=null,deletingMealId=null,deleteKind=null;
function go(page){const dashboard=page==='dashboard',isWorkouts=page==='workouts',isMeals=page==='meals';$('#dashboard').classList.toggle('hidden',!dashboard);$('#workouts').classList.toggle('hidden',!isWorkouts);$('#meals').classList.toggle('hidden',!isMeals);$('#coming').classList.toggle('hidden',dashboard||isWorkouts||isMeals);$('#page-title').textContent=names[page];$('#kicker').textContent=dashboard?'YOUR PERSONAL SPACE':'FITNESS TRACKER';$('#coming-title').textContent=names[page];document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(isWorkouts)loadWorkouts();if(isMeals)loadMeals();$('#more-menu').classList.add('hidden');scrollTo({top:0,behavior:'smooth'})}
function number(value){const result=Number(value);return Number.isFinite(result)?result:0}function quantity(value){return Number.isInteger(value)?String(value):String(Math.round(value*100)/100)}
function renderMealSummary(){const totals=meals.reduce((sum,meal)=>({calories:sum.calories+number(meal.calories),protein:sum.protein+number(meal.protein),carbs:sum.carbs+number(meal.carbs),fat:sum.fat+number(meal.fat)}),{calories:0,protein:0,carbs:0,fat:0});$('#meal-summary').innerHTML=[['Total meals',meals.length],['Total calories',`${totals.calories.toLocaleString()} kcal`],['Protein',`${quantity(totals.protein)} g`],['Carbohydrates',`${quantity(totals.carbs)} g`],['Fat',`${quantity(totals.fat)} g`]].map(item=>`<article><div class="stat-label">${item[0]}</div><strong>${item[1]}</strong><small>From your meal history</small></article>`).join('')}
function renderMeals(){renderMealSummary();const content=$('#meal-content');if(!meals.length){content.innerHTML='<div class="state"><span class="tile">Meal</span><h3>No meals recorded yet</h3><p>Start tracking your meals to monitor your nutrition.</p><button class="button primary" id="empty-add-meal">Add Meal</button></div>';$('#empty-add-meal').onclick=openAddMeal;return}content.innerHTML=`<table class="meal-table"><thead><tr><th>Date</th><th>Meal</th><th>Food</th><th>Calories</th><th>Protein</th><th>Carbs</th><th>Fat</th><th>Actions</th></tr></thead><tbody>${meals.map(meal=>`<tr><td>${formatDate(meal.date)}</td><td>${escapeHtml(meal.mealType)}</td><td class="food-name">${escapeHtml(meal.foodName)}</td><td>${number(meal.calories)} kcal</td><td>${quantity(number(meal.protein))} g</td><td>${quantity(number(meal.carbs))} g</td><td>${quantity(number(meal.fat))} g</td><td><div class="actions"><button class="action" data-edit-meal="${meal.id}">Edit</button><button class="action delete-action" data-delete-meal="${meal.id}">Delete</button></div></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-edit-meal]').forEach(button=>button.onclick=()=>openEditMeal(Number(button.dataset.editMeal)));document.querySelectorAll('[data-delete-meal]').forEach(button=>button.onclick=()=>openDeleteMeal(Number(button.dataset.deleteMeal)))}
async function loadMeals(){const content=$('#meal-content');content.innerHTML='<div class="state">Loading meals...</div>';try{const response=await fetch(`/api/meals/user/${USER_ID}`);if(!response.ok)throw Error(`HTTP ${response.status}`);meals=(await response.json()).sort((a,b)=>b.date.localeCompare(a.date));renderMeals()}catch(error){console.error('Unable to load meals:',error);$('#meal-summary').innerHTML='';content.innerHTML='<div class="state"><h3>Unable to load meals.</h3><p>Please check that the backend is running and try again.</p><button class="button secondary" id="state-retry-meals">Retry</button></div>';$('#state-retry-meals').onclick=loadMeals}}
function openAddMeal(){editingMealId=null;$('#meal-modal-title').textContent='Add Meal';$('#save-meal').textContent='Add Meal';$('#meal-form').reset();$('#meal-date').value=new Date().toISOString().slice(0,10);$('#meal-form-error').classList.add('hidden');$('#meal-modal').classList.remove('hidden');$('#meal-date').focus()}function openEditMeal(id){const meal=meals.find(item=>item.id===id);if(!meal)return;editingMealId=id;$('#meal-modal-title').textContent='Edit Meal';$('#save-meal').textContent='Save Changes';$('#meal-date').value=meal.date;$('#meal-type').value=meal.mealType;$('#food-name').value=meal.foodName;$('#meal-calories').value=meal.calories;$('#meal-protein').value=meal.protein;$('#meal-carbs').value=meal.carbs;$('#meal-fat').value=meal.fat;$('#meal-form-error').classList.add('hidden');$('#meal-modal').classList.remove('hidden')}function closeMealModal(){$('#meal-modal').classList.add('hidden')}
async function saveMeal(event){event.preventDefault();const form=$('#meal-form');if(!form.reportValidity())return;const payload={user:{id:USER_ID},date:$('#meal-date').value,mealType:$('#meal-type').value,foodName:$('#food-name').value.trim(),calories:number($('#meal-calories').value),protein:number($('#meal-protein').value),carbs:number($('#meal-carbs').value),fat:number($('#meal-fat').value)};if(!payload.foodName||[payload.calories,payload.protein,payload.carbs,payload.fat].some(value=>value<0)){showMealError('Please complete all fields with non-negative values.');return}try{const response=await fetch(editingMealId?`/api/meals/${editingMealId}`:'/api/meals',{method:editingMealId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(`HTTP ${response.status}`);closeMealModal();toast(editingMealId?'Meal updated successfully.':'Meal added successfully.');await loadMeals()}catch(error){console.error('Unable to save meal:',error);showMealError('Unable to save meal. Please try again.')}}function showMealError(message){$('#meal-form-error').textContent=message;$('#meal-form-error').classList.remove('hidden')}
function openDeleteMeal(id){deletingMealId=id;deleteKind='meal';$('#delete-title').textContent='Delete this meal?';$('#delete-modal').classList.remove('hidden')}function openDelete(id){deletingId=id;deleteKind='workout';$('#delete-title').textContent='Delete this workout?';$('#delete-modal').classList.remove('hidden')}async function confirmDelete(){if(deleteKind==='meal'){try{const response=await fetch(`/api/meals/${deletingMealId}`,{method:'DELETE'});if(!response.ok)throw Error();$('#delete-modal').classList.add('hidden');toast('Meal deleted successfully.');await loadMeals()}catch(error){console.error('Unable to delete meal:',error);$('#delete-modal').classList.add('hidden');toast('Unable to delete meal. Please try again.',true)}}else await deleteWorkout()}
