function go(page){const dashboard=page==='dashboard',isWorkouts=page==='workouts',isMeals=page==='meals',isGoals=page==='goals';$('#dashboard').classList.toggle('hidden',!dashboard);$('#workouts').classList.toggle('hidden',!isWorkouts);$('#meals').classList.toggle('hidden',!isMeals);$('#goals').classList.toggle('hidden',!isGoals);$('#coming').classList.toggle('hidden',dashboard||isWorkouts||isMeals||isGoals);$('#page-title').textContent=names[page];$('#kicker').textContent=dashboard?'YOUR PERSONAL SPACE':'FITNESS TRACKER';$('#coming-title').textContent=names[page];document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(isWorkouts)loadWorkouts();if(isMeals)loadMeals();if(isGoals)loadGoals();$('#more-menu').classList.add('hidden');scrollTo({top:0,behavior:'smooth'})}
function goalProgress(goal){const target=number(goal.targetValue),current=number(goal.currentValue);return target>0?Math.max(0,Math.min(100,Math.round(current/target*100))):0}function statusClass(status){const value=String(status||'').toLowerCase();return value==='completed'?'completed':value.includes('progress')?'active':'other'}
function renderGoalSummary(){const total=goals.length,completed=goals.filter(goal=>String(goal.status).toLowerCase()==='completed').length,active=total-completed,average=total?Math.round(goals.reduce((sum,goal)=>sum+goalProgress(goal),0)/total):0;$('#goal-summary').innerHTML=[['Total goals',total],['Active goals',active],['Completed goals',completed],['Average progress',`${average}%`]].map(item=>`<article><div class="stat-label">${item[0]}</div><strong>${item[1]}</strong><small>From your goals</small></article>`).join('')}
function renderGoals(){renderGoalSummary();const content=$('#goal-content');if(!goals.length){content.innerHTML='<div class="state"><span class="tile">Goal</span><h3>No goals yet</h3><p>Set your first goal and start tracking your progress.</p><button class="button primary" id="empty-add-goal">Add Goal</button></div>';$('#empty-add-goal').onclick=openAddGoal;return}content.innerHTML=goals.map(goal=>{const progress=goalProgress(goal);return `<article class="goal-card"><div><h4>${escapeHtml(goal.goalType)}</h4><p>${formatDate(goal.startDate)} to ${goal.targetDate?formatDate(goal.targetDate):'No target date'}</p></div><div class="goal-metric"><small>Current</small><strong>${quantity(number(goal.currentValue))}</strong></div><div class="goal-metric"><small>Target</small><strong>${quantity(number(goal.targetValue))}</strong></div><div class="goal-progress"><div class="progress"><i style="width:${progress}%"></i></div><p class="percent">${progress}% complete</p><span class="status ${statusClass(goal.status)}">${escapeHtml(goal.status)}</span></div><div class="actions"><button class="action" data-edit-goal="${goal.id}">Edit</button><button class="action delete-action" data-delete-goal="${goal.id}">Delete</button></div></article>`}).join('');document.querySelectorAll('[data-edit-goal]').forEach(button=>button.onclick=()=>openEditGoal(Number(button.dataset.editGoal)));document.querySelectorAll('[data-delete-goal]').forEach(button=>button.onclick=()=>openDeleteGoal(Number(button.dataset.deleteGoal)))}
async function loadGoals(){const content=$('#goal-content');content.innerHTML='<div class="state">Loading goals...</div>';try{const response=await fetch(`/api/goals/user/${USER_ID}`);if(!response.ok)throw Error(`HTTP ${response.status}`);goals=await response.json();renderGoals()}catch(error){console.error('Unable to load goals:',error);$('#goal-summary').innerHTML='';content.innerHTML='<div class="state"><h3>Unable to load goals.</h3><p>Please check that the backend is running and try again.</p><button class="button secondary" id="state-retry-goals">Retry</button></div>';$('#state-retry-goals').onclick=loadGoals}}
function openAddGoal(){editingGoalId=null;$('#goal-modal-title').textContent='Add Goal';$('#save-goal').textContent='Add Goal';$('#goal-form').reset();$('#goal-start').value=new Date().toISOString().slice(0,10);$('#goal-form-error').classList.add('hidden');$('#goal-modal').classList.remove('hidden');$('#goal-type').focus()}function openEditGoal(id){const goal=goals.find(item=>item.id===id);if(!goal)return;editingGoalId=id;$('#goal-modal-title').textContent='Edit Goal';$('#save-goal').textContent='Save Changes';$('#goal-type').value=goal.goalType;$('#goal-target').value=goal.targetValue;$('#goal-current').value=goal.currentValue;$('#goal-start').value=goal.startDate;$('#goal-end').value=goal.targetDate||'';$('#goal-status').value=goal.status;$('#goal-form-error').classList.add('hidden');$('#goal-modal').classList.remove('hidden')}function closeGoalModal(){$('#goal-modal').classList.add('hidden')}
async function saveGoal(event){event.preventDefault();const form=$('#goal-form');if(!form.reportValidity())return;const payload={user:{id:USER_ID},goalType:$('#goal-type').value.trim(),targetValue:number($('#goal-target').value),currentValue:number($('#goal-current').value),startDate:$('#goal-start').value,targetDate:$('#goal-end').value,status:$('#goal-status').value};if(!payload.goalType||payload.targetValue<=0||payload.currentValue<0||payload.targetDate<payload.startDate){showGoalError('Check all fields and ensure the target date is not before the start date.');return}try{const response=await fetch(editingGoalId?`/api/goals/${editingGoalId}`:'/api/goals',{method:editingGoalId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(`HTTP ${response.status}`);closeGoalModal();toast(editingGoalId?'Goal updated successfully.':'Goal added successfully.');await loadGoals()}catch(error){console.error('Unable to save goal:',error);showGoalError('Unable to save goal. Please try again.')}}function showGoalError(message){$('#goal-form-error').textContent=message;$('#goal-form-error').classList.remove('hidden')}
function openDeleteGoal(id){deletingGoalId=id;deleteKind='goal';$('#delete-title').textContent='Delete this goal?';$('#delete-modal').classList.remove('hidden')}async function confirmDelete(){if(deleteKind==='goal'){try{const response=await fetch(`/api/goals/${deletingGoalId}`,{method:'DELETE'});if(!response.ok)throw Error();$('#delete-modal').classList.add('hidden');toast('Goal deleted successfully.');await loadGoals()}catch(error){console.error('Unable to delete goal:',error);$('#delete-modal').classList.add('hidden');toast('Unable to delete goal. Please try again.',true)}}else if(deleteKind==='meal'){try{const response=await fetch(`/api/meals/${deletingMealId}`,{method:'DELETE'});if(!response.ok)throw Error();$('#delete-modal').classList.add('hidden');toast('Meal deleted successfully.');await loadMeals()}catch(error){console.error('Unable to delete meal:',error);toast('Unable to delete meal. Please try again.',true)}}else await deleteWorkout()}
