let profileData=null;function safeProfile(value,unit=''){const parsed=Number(value);if(unit&&Number.isFinite(parsed))return `${quantity(parsed)}${unit}`;return value===null||value===undefined||value===''?'—':String(value)}function memberDate(value){if(!value||typeof value!=='string')return '—';const match=value.match(/^\d{4}-\d{2}-\d{2}/);return match?formatDate(match[0]):'—'}
