async function loadProfile(){const content=$('#profile-content');content.innerHTML='<div class="state">Loading profile...</div>';try{const response=await fetch(`/api/users/${USER_ID}`);if(!response.ok)throw Error(`HTTP ${response.status}`);profileData=await response.json();if(!profileData||typeof profileData!=='object')throw Error('Malformed profile response');renderProfile()}catch(error){console.error('Unable to load profile:',error);profileData=null;renderProfile()}}
function openProfileModal(){$('#profile-name').value=profileData.name||'';$('#profile-email').value=profileData.email||'';$('#profile-age').value=profileData.age||'';$('#profile-height').value=profileData.height||'';$('#profile-weight').value=profileData.weight||'';$('#profile-form-error').classList.add('hidden');$('#profile-modal').classList.remove('hidden');$('#profile-name').focus()}function closeProfileModal(){$('#profile-modal').classList.add('hidden')}async function saveProfile(event){event.preventDefault();const form=$('#profile-form');if(!form.reportValidity())return;const payload={name:$('#profile-name').value.trim(),email:$('#profile-email').value.trim(),age:number($('#profile-age').value),height:number($('#profile-height').value),weight:number($('#profile-weight').value)};if(!payload.name||!payload.email||payload.age<=0||payload.height<=0||payload.weight<=0){showProfileError('Enter valid profile information.');return}try{const response=await fetch(`/api/users/${USER_ID}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(`HTTP ${response.status}`);closeProfileModal();toast('Profile updated successfully.');await loadProfile()}catch(error){console.error('Unable to update profile:',error);showProfileError('Unable to update profile. Please try again.')}}function showProfileError(message){$('#profile-form-error').textContent=message;$('#profile-form-error').classList.remove('hidden')}
function applyPreferences(){const theme=localStorage.getItem('fitnessTrackerTheme')||'dark',reduced=localStorage.getItem('fitnessTrackerReducedMotion')==='true';document.body.classList.toggle('light-theme',theme==='light');document.body.classList.toggle('reduce-motion',reduced);document.querySelectorAll('[data-theme]').forEach(button=>button.classList.toggle('active',button.dataset.theme===theme));$('#reduced-motion').checked=reduced}function setTheme(theme){localStorage.setItem('fitnessTrackerTheme',theme);applyPreferences();toast('Preferences updated.')}function setReducedMotion(value){localStorage.setItem('fitnessTrackerReducedMotion',String(value));applyPreferences();toast('Preferences updated.')}function resetPreferences(){localStorage.removeItem('fitnessTrackerTheme');localStorage.removeItem('fitnessTrackerReducedMotion');applyPreferences();toast('Preferences reset.')}
function go(page){const dashboard=page==='dashboard',isWorkouts=page==='workouts',isMeals=page==='meals',isGoals=page==='goals',isProgress=page==='progress',isAnalytics=page==='analytics',isProfile=page==='profile'||page==='settings';$('#dashboard').classList.toggle('hidden',!dashboard);$('#workouts').classList.toggle('hidden',!isWorkouts);$('#meals').classList.toggle('hidden',!isMeals);$('#goals').classList.toggle('hidden',!isGoals);$('#progress').classList.toggle('hidden',!isProgress);$('#analytics').classList.toggle('hidden',!isAnalytics);$('#profile-settings').classList.toggle('hidden',!isProfile);$('#coming').classList.toggle('hidden',dashboard||isWorkouts||isMeals||isGoals||isProgress||isAnalytics||isProfile);$('#page-title').textContent=isProfile?'Profile & Settings':names[page];$('#kicker').textContent=dashboard?'YOUR PERSONAL SPACE':'FITNESS TRACKER';$('#coming-title').textContent=names[page];document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(isWorkouts)loadWorkouts();if(isMeals)loadMeals();if(isGoals)loadGoals();if(isProgress)loadWeightLogs();if(isAnalytics)loadAnalytics();if(isProfile)loadProfile();$('#more-menu').classList.add('hidden');scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',event=>{if(event.target.matches('[data-close-profile]'))closeProfileModal();const theme=event.target.closest('[data-theme]');if(theme)setTheme(theme.dataset.theme)});$('#profile-form').onsubmit=saveProfile;$('#reduced-motion').onchange=event=>setReducedMotion(event.target.checked);$('#reset-preferences').onclick=resetPreferences;applyPreferences();

// Final shared safeguards: consistent navigation, date display, and modal dismissal.
function formatDate(date){if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date))return '—';const value=new Date(`${date}T00:00:00`);return Number.isNaN(value.getTime())?'—':new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(value)}
function number(value){const result=Number(value);return Number.isFinite(result)?result:0}
function quantity(value){const result=number(value);return Number.isInteger(result)?String(result):String(Math.round(result*100)/100)}
function formatMinutes(value){const minutes=Math.max(0,Math.round(number(value)));return minutes>=60?`${Math.floor(minutes/60)}h ${minutes%60}m`:`${minutes} min`}
function closeActiveModal(){document.querySelectorAll('.modal:not(.hidden)').forEach(modal=>modal.classList.add('hidden'))}
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeActiveModal()});
document.addEventListener('click',event=>{if(event.target.classList.contains('modal'))closeActiveModal()});
$('.profile').onclick=()=>go('profile');
document.querySelectorAll('.icon-button').forEach(button=>{button.type='button';if(!button.getAttribute('aria-label'))button.setAttribute('aria-label','Close dialog');button.textContent='×'});
document.querySelectorAll('.modal').forEach(modal=>{modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true')});
const lovableStyles=document.createElement('link');lovableStyles.rel='stylesheet';lovableStyles.href='css/lovable-ui.css';document.head.append(lovableStyles);
const iconPaths={dashboard:'M3 3h7v7H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 14h7v7H3z',workout:'M6 7v10M18 7v10M3 10h3M3 14h3M18 10h3M18 14h3M6 12h12',meal:'M7 3v8M4 3v5a3 3 0 0 0 6 0V3M7 11v10M17 3v18M17 3c3 0 3 6 0 6',goal:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 18a6 6 0 1 0 0-12 6 6 0 0 0 0 12ZM12 14a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z',progress:'M4 19 10 13l4 4 6-8M16 9h4v4',analytics:'M4 20V10M10 20V4M16 20v-7M22 20H2',profile:'M20 21a8 8 0 0 0-16 0M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.12 2.12-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.04 1.56V20h-3v-.08A1.7 1.7 0 0 0 10.66 18.36a1.7 1.7 0 0 0-1.88.34l-.06.06-2.12-2.12.06-.06A1.7 1.7 0 0 0 7 14.7a1.7 1.7 0 0 0-1.56-1.04H5v-3h.08A1.7 1.7 0 0 0 6.64 9.62a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.12-2.12.06.06A1.7 1.7 0 0 0 10.3 6a1.7 1.7 0 0 0 1.04-1.56V4h3v.08A1.7 1.7 0 0 0 15.38 5.64a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.12 2.12-.06.06A1.7 1.7 0 0 0 19 9.3a1.7 1.7 0 0 0 1.56 1.04H21v3h-.08A1.7 1.7 0 0 0 19.4 15Z',add:'M12 5v14M5 12h14',edit:'m4 20 4-1 10-10-3-3L5 16l-1 4ZM13 6l3 3',delete:'M4 7h16M10 11v5M14 11v5M9 7l1-3h4l1 3M6 7l1 14h10l1-14',refresh:'M20 11a8 8 0 1 0 2 5M20 4v7h-7',close:'M6 6l12 12M18 6 6 18',activity:'M4 13h4l2-7 4 13 2-6h4',scale:'M4 5h16v15H4zM8 10a4 4 0 0 1 8 0M12 10l2-2'};
function svgIcon(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.activity}"/></svg>`}function insertIcon(element,name){if(!element||element.dataset.iconApplied)return;element.dataset.iconApplied='true';element.insertAdjacentHTML('afterbegin',svgIcon(name))}function workoutIconName(value){const type=String(value||'').toLowerCase();return type.includes('strength')||type.includes('weight')?'workout':type.includes('run')||type.includes('walk')||type.includes('cardio')||type.includes('hiit')||type.includes('cycl')||type.includes('swim')||type.includes('yoga')?'activity':'workout'}
function enhanceIconography(){const navIcons={dashboard:'dashboard',workouts:'workout',meals:'meal',goals:'goal',progress:'progress',analytics:'analytics',profile:'profile',settings:'settings'};document.querySelectorAll('[data-page]').forEach(button=>insertIcon(button,navIcons[button.dataset.page]||'activity'));document.querySelectorAll('.workout-type').forEach(item=>insertIcon(item,workoutIconName(item.textContent)));document.querySelectorAll('.meal-table td:nth-child(2),.food-name').forEach(item=>insertIcon(item,'meal'));document.querySelectorAll('.goal-card h4').forEach(item=>insertIcon(item,'goal'));document.querySelectorAll('.activity i').forEach(item=>{if(item.dataset.iconApplied)return;const meal=item.textContent.trim()==='M';item.innerHTML=svgIcon(meal?'meal':'workout');item.dataset.iconApplied='true'});document.querySelectorAll('.tile').forEach(item=>{if(item.dataset.iconApplied)return;const hint=item.closest('#meals')?'meal':item.closest('#goals')?'goal':item.closest('#progress')?'scale':'workout';item.innerHTML=svgIcon(hint);item.dataset.iconApplied='true'});document.querySelectorAll('.action').forEach(button=>{const deleting=button.classList.contains('delete-action');button.title=deleting?'Delete':'Edit';button.setAttribute('aria-label',button.title);if(!button.dataset.iconApplied){button.dataset.iconApplied='true';button.innerHTML=svgIcon(deleting?'delete':'edit')}});document.querySelectorAll('[id^="add-"],#empty-add,#empty-add-meal,#empty-add-goal,#empty-add-weight').forEach(button=>insertIcon(button,'add'));document.querySelectorAll('.link').forEach(button=>insertIcon(button,'refresh'));document.querySelectorAll('.icon-button').forEach(button=>{if(button.dataset.iconApplied)return;button.dataset.iconApplied='true';button.innerHTML=svgIcon('close');button.setAttribute('aria-label','Close dialog')})}
const polishStyles=document.createElement('link');polishStyles.rel='stylesheet';polishStyles.href='css/polish-ui.css';document.head.append(polishStyles);const iconObserver=new MutationObserver(()=>enhanceIconography());iconObserver.observe(document.body,{childList:true,subtree:true});enhanceIconography();
// Final interaction fixes: SVG clicks resolve through their owning control, and navigation has one visible label.
function normalizeNavigationLabels(){document.querySelectorAll('button[data-page]').forEach(button=>{if(!button.querySelector(':scope > span'))return;Array.from(button.childNodes).filter(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim()).forEach(node=>node.remove())})}normalizeNavigationLabels();
function addMoreNavigationIcon(){const more=$('#more');if(!more||more.dataset.iconApplied)return;more.dataset.iconApplied='true';more.insertAdjacentHTML('afterbegin','<svg class="ui-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="19" cy="12" r="1.7"/></svg>');Array.from(more.childNodes).filter(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim()).forEach(node=>node.remove())}addMoreNavigationIcon();
const finalFixStyles=document.createElement('link');finalFixStyles.rel='stylesheet';finalFixStyles.href='css/final-fixes.css';document.head.append(finalFixStyles);
document.addEventListener('click',event=>{const close=event.target.closest('[data-close-modal],[data-close-meal],[data-close-goal],[data-close-weight],[data-close-profile],[data-close-delete]');if(close){closeActiveModal();return}const settings=event.target.closest('[data-page="settings"]');if(settings){setTimeout(()=>document.querySelector('.preferences')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}});
function guardSubmission(form,handler,button){if(!form||!handler||!button)return;form.onsubmit=async event=>{event.preventDefault();if(form.dataset.submitting==='true')return;form.dataset.submitting='true';const original=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Saving…';try{await handler(event)}finally{form.dataset.submitting='false';button.disabled=false;button.removeAttribute('aria-busy');button.textContent=original;enhanceIconography()}}}
guardSubmission($('#workout-form'),saveWorkout,$('#save-workout'));guardSubmission($('#meal-form'),saveMeal,$('#save-meal'));guardSubmission($('#goal-form'),saveGoal,$('#save-goal'));guardSubmission($('#weight-form'),saveWeight,$('#save-weight'));guardSubmission($('#profile-form'),saveProfile,$('#profile-form button[type="submit"]'));
function addAccountContext(){const profileActions=$('#profile-content .profile-actions');if(!profileActions||$('#account-context'))return;profileActions.insertAdjacentHTML('afterend','<section class="account-context" id="account-context"><span class="account-context-icon">'+svgIcon('profile')+'</span><div><strong>Current profile</strong><p>This academic project uses one active fitness profile. Authentication is not required for its current scope.</p></div></section>')}const profileObserver=new MutationObserver(addAccountContext);const profileContent=$('#profile-content');if(profileContent)profileObserver.observe(profileContent,{childList:true});addAccountContext();

// Lovable-inspired live overview. Detailed pages remain the source for CRUD actions.
async function renderDashboard(){
 const stats=$('#stats'),bars=$('#week-bars'),goalHolder=$('#goals-list'),nutrition=$('#nutrition'),recent=$('#recent-list');
 if(!stats||!bars||!goalHolder||!nutrition||!recent)return;
 stats.innerHTML='<article><div class="stat-label">Loading overview</div><strong>…</strong><small>Fetching your fitness data</small></article>';
 try{
  const [userResponse,workoutResponse,mealResponse,goalResponse,weightResponse,analyticsResponse]=await Promise.all([
   fetch(`/api/users/${USER_ID}`),fetch(`/api/workouts/user/${USER_ID}`),fetch(`/api/meals/user/${USER_ID}`),fetch(`/api/goals/user/${USER_ID}`),fetch(`/api/weight-logs/user/${USER_ID}`),fetch(`/api/analytics/weekly/${USER_ID}`)
  ]);
  if(![userResponse,workoutResponse,mealResponse,goalResponse,weightResponse,analyticsResponse].every(response=>response.ok))throw Error('Unable to load dashboard data');
  const [user,liveWorkouts,liveMeals,liveGoals,liveWeights,analytics]=await Promise.all([userResponse.json(),workoutResponse.json(),mealResponse.json(),goalResponse.json(),weightResponse.json(),analyticsResponse.json()]);
  const firstName=String(user.name||'there').trim().split(/\s+/)[0]||'there';
  document.querySelectorAll('.welcome h2').forEach(element=>element.textContent=`Good morning, ${firstName}`);
  document.querySelectorAll('.profile span').forEach(element=>element.textContent=firstName);
  document.querySelectorAll('.profile').forEach(element=>element.firstChild.nodeValue=(firstName[0]||'U').toUpperCase());
  stats.innerHTML=[['Workouts this week',String(number(analytics.totalWorkouts)),'Live weekly activity'],['Workout time',formatMinutes(analytics.totalWorkoutDuration),'From completed sessions'],['Calories burned',`${number(analytics.totalCaloriesBurned).toLocaleString()} kcal`,'Workout total'],['Active goals',String(liveGoals.filter(goal=>String(goal.status).toLowerCase()!=='completed').length),'Goals in progress']].map(([label,value,hint])=>`<article><div class="stat-label">${label}</div><strong>${value}</strong><small>${hint}</small></article>`).join('');
  const start=new Date(`${analytics.weekStart}T00:00:00`);bars.innerHTML=Array.from({length:7},(_,index)=>{const date=new Date(start);date.setDate(start.getDate()+index);const key=date.toISOString().slice(0,10);const count=liveWorkouts.filter(workout=>workout.date===key).length;return `<div class="day ${count?'active':''}"><i style="height:${count?Math.min(100,25+count*30):8}%"></i><span>${new Intl.DateTimeFormat('en-US',{weekday:'short'}).format(date)}</span></div>`}).join('');
  const orderedGoals=liveGoals.slice().sort((a,b)=>String(a.status).localeCompare(String(b.status))).slice(0,2);
  goalHolder.innerHTML=orderedGoals.length?orderedGoals.map(goal=>{const progress=goalProgress(goal);return `<article class="goal"><div class="goal-top"><strong>${escapeHtml(goal.goalType)}</strong><span>${quantity(goal.currentValue)} / ${quantity(goal.targetValue)}</span></div><p>${escapeHtml(goal.status||'In Progress')}</p><div class="progress"><i style="width:${progress}%"></i></div><p class="percent">${progress}% complete</p></article>`}).join(''):'<div class="state"><h3>No goals yet</h3><p>Create a goal to track your progress.</p></div>';
  const totals=liveMeals.reduce((sum,meal)=>({calories:sum.calories+number(meal.calories),protein:sum.protein+number(meal.protein),carbs:sum.carbs+number(meal.carbs),fat:sum.fat+number(meal.fat)}),{calories:0,protein:0,carbs:0,fat:0});
  nutrition.innerHTML=[['Calories',`${totals.calories.toLocaleString()} kcal`],['Protein',`${quantity(totals.protein)} g`],['Carbs',`${quantity(totals.carbs)} g`],['Fat',`${quantity(totals.fat)} g`]].map(([label,value])=>`<div><span>${label}</span><b>${value}</b></div>`).join('');
  const activity=[...liveWorkouts.map(workout=>({kind:'Workout',name:workout.type,when:workout.date,meta:`${number(workout.duration)} min`})),...liveMeals.map(meal=>({kind:'Meal',name:meal.foodName,when:meal.date,meta:`${number(meal.calories)} kcal`}))].sort((a,b)=>String(b.when).localeCompare(String(a.when))).slice(0,5);
  recent.innerHTML=activity.length?activity.map(item=>`<article class="activity"><i>${item.kind==='Meal'?'M':'W'}</i><div><b>${escapeHtml(item.name)}</b><small>${formatDate(item.when)}</small></div><span>${item.meta}</span></article>`).join(''):'<div class="state"><h3>No activity yet</h3><p>Add a workout or meal to begin.</p></div>';
  const recentWeights=liveWeights.filter(item=>item.date).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(-8);
  const chart=document.querySelector('#dashboard .chart');
  if(chart){if(recentWeights.length<2){chart.innerHTML='<div class="trend-empty">Add at least two weight entries to view a live trend.</div>'}else{const values=recentWeights.map(item=>number(item.weight)),min=Math.min(...values),max=Math.max(...values),range=max-min||1,width=500,height=150,pad=12;const point=(item,index)=>`${index?'L':'M'} ${pad+(width-pad*2)*index/(recentWeights.length-1)} ${pad+(height-pad*2)*(1-(number(item.weight)-min)/range)}`;chart.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Recent weight trend"><path class="area" d="${recentWeights.map(point).join(' ')} L ${width-pad} ${height-pad} L ${pad} ${height-pad} Z"/><path class="line" d="${recentWeights.map(point).join(' ')}"/></svg>`}}
 }catch(error){console.error('Unable to load dashboard:',error);stats.innerHTML='<article><div class="stat-label">Dashboard unavailable</div><strong>—</strong><small>Use a detailed page and try again.</small></article>';bars.innerHTML='';goalHolder.innerHTML='';nutrition.innerHTML='';recent.innerHTML='<div class="state"><h3>Unable to load activity</h3><p>Please check the connection and refresh.</p></div>'}
}
